/** Typed constructors for JSON/XML structure nodes. Avoids authoring wire discriminant strings. */
export const fileReaderStructure = {
    text: (name) => ({ type: "text", name }),
    number: (name) => ({ type: "number", name }),
    decimal: (name) => ({ type: "decimal", name }),
    boolean: (name) => ({ type: "boolean", name }),
    date: (name, format) => ({ type: "date", name, format }),
    datetime: (name, format) => ({ type: "datetime", name, format }),
    object: (name, properties) => ({ type: "object", name, properties }),
    array: (name, itemType) => ({ type: "array", name, itemType }),
};
export const fileReaderFieldType = {
    text: "TEXT",
    number: "NUMBER",
    decimal: "DECIMAL",
    boolean: "BOOLEAN",
    date: "DATE",
    datetime: "DATETIME",
    picklist: "PICKLIST",
    userId: "USER_ID",
    groupId: "GROUP_ID",
    html: "HTML",
    localizationKey: "LOCALIZATION_KEY",
    uuid: "UUID",
};
function configureFileReader(opts) {
    return {
        ref(refName) {
            return { __kind: "documentModel", refName, name: opts.name, parent: opts.owner.refName, readerType: opts.type };
        },
        def(refName) {
            const { owner, enabled, ...payload } = opts;
            return {
                kind: "documentModel",
                parent: owner.refName,
                refName,
                payload,
                ...(enabled !== undefined ? { enabled } : {}),
            };
        },
    };
}
/** Extract structured values with an AI model. */
export function aiFileReader(opts) {
    return configureFileReader({ ...opts, type: "ai" });
}
/** Extract fixed cell locations from a spreadsheet. */
export function excelFileReader(opts) {
    return configureFileReader({ ...opts, type: "excel" });
}
/** Extract a typed JSON structure. */
export function jsonFileReader(opts) {
    return configureFileReader({ ...opts, type: "json" });
}
/** Read freeform text. */
export function textFileReader(opts) {
    return configureFileReader({ ...opts, type: "text" });
}
/** Extract a typed XML structure. */
export function xmlFileReader(opts) {
    return configureFileReader({ ...opts, type: "xml" });
}
function serializeJsonStructureField(f) {
    switch (f.type) {
        case "text":
            return { text: { name: f.name } };
        case "number":
            return { number: { name: f.name } };
        case "decimal":
            return { decimal: { name: f.name } };
        case "boolean":
            return { bool: { name: f.name } };
        case "date":
            return { date: { name: f.name, format: f.format } };
        case "datetime":
            return { datetime: { name: f.name, format: f.format } };
        case "object":
            return { object: { name: f.name, properties: f.properties.map(serializeJsonStructureField) } };
        case "array":
            return { array: { name: f.name, arrayType: serializeJsonStructureField(f.itemType) } };
    }
}
function serializeJsonStructure(fields) {
    return { properties: fields.map(serializeJsonStructureField) };
}
function serializeAiFields(fields) {
    return fields.map((f) => ({ name: f.name, description: f.description, required: f.required, type: f.type }));
}
function serializeExcelFields(fields) {
    return fields.map((f) => ({
        fieldType: f.fieldType,
        required: f.required,
        include: f.include,
        ...(f.name !== undefined ? { name: f.name } : {}),
        ...(f.location !== undefined ? { location: f.location } : {}),
    }));
}
/** @deprecated Pre-terraform API. Build the `documentModelCreate` mutation input from a document model's authored payload. */
export function fileReaderCreateBody(opts) {
    switch (opts.type) {
        case "ai":
            return { ai: { name: opts.name, instructions: opts.instructions, fields: serializeAiFields(opts.fields) } };
        case "excel":
            return {
                excel: {
                    name: opts.name,
                    documentId: opts.documentId,
                    firstRowIsHeader: opts.firstRowIsHeader,
                    fields: serializeExcelFields(opts.fields),
                },
            };
        case "excelCell":
            return {
                excelCell: { name: opts.name, documentId: opts.documentId, fields: serializeExcelFields(opts.fields) },
            };
        case "invoice":
            return { invoice: { name: opts.name, fields: opts.fields } };
        case "json":
            return { json: { name: opts.name, jsonStructure: serializeJsonStructure(opts.structure) } };
        case "ocr":
            return { ocr: { name: opts.name } };
        case "xml":
            return { xml: { name: opts.name, values: serializeJsonStructure(opts.structure) } };
    }
}
/**
 * @deprecated Pre-terraform API. Build the `documentModelUpdate` mutation
 * input. `excelCell` has no update path on the graph for its own content —
 * only `name` — so callers must route any other excelCell change to
 * update-unsupported themselves before calling this with excelCell content
 * changes.
 */
export function fileReaderUpdateBody(opts) {
    switch (opts.type) {
        case "ai":
            return { name: opts.name, ai: { name: opts.name, instructions: opts.instructions, fields: serializeAiFields(opts.fields) } };
        case "excel":
            return { name: opts.name, excelFields: serializeExcelFields(opts.fields) };
        case "excelCell":
            return { name: opts.name };
        case "invoice":
            return { name: opts.name, invoiceFields: opts.fields };
        case "json":
            return { name: opts.name, jsonStructure: serializeJsonStructure(opts.structure) };
        case "ocr":
            return { name: opts.name };
        case "xml":
            return { name: opts.name, xml: { name: opts.name, values: serializeJsonStructure(opts.structure) } };
    }
}
